    ["|cffffff78/ttpaste |r - Open a window to paste and execute multiple TomTom commands"] = "|cffffff78/ttpaste |r — открыть окно массовой вставки команд",
    ["|cffffff78/way /tway /tomtomway |r - Commands to set a waypoint: one should work."] = "|cffffff78/way /tway /tomtomway |r — команды создания точки (используйте любую)",
    ["|cffffff78/way <x> <y> [desc]|r - Adds a waypoint at x,y with description desc"] = "|cffffff78/way <x> <y> [описание]|r — добавить точку в x,y с описанием",
    ["|cffffff78/way <zone> <x> <y> [desc]|r - Adds a waypoint at x,y in zone with description desc"] = "|cffffff78/way <зона> <x> <y> [описание]|r — добавить точку в указанной зоне",
